import requests

class InventoryClientError(RuntimeError):
    pass

def fetch_stock(url: str) -> int:
    try:
        response = requests.get(url, timeout=(3.05, 8))
        response.raise_for_status()
        data = response.json()
    except requests.exceptions.Timeout as exc:
        raise InventoryClientError("inventory request timed out") from exc
    except requests.exceptions.HTTPError as exc:
        raise InventoryClientError(
            f"inventory returned HTTP {exc.response.status_code}"
        ) from exc
    except requests.exceptions.JSONDecodeError as exc:
        raise InventoryClientError("inventory returned invalid JSON") from exc
    except requests.exceptions.RequestException as exc:
        raise InventoryClientError("inventory transport failed") from exc

    quantity = data.get("quantity") if isinstance(data, dict) else None
    if not isinstance(quantity, int) or quantity < 0:
        raise InventoryClientError("inventory quantity is invalid")
    return quantity
```

